outputs = ['zkexdfkexudfkexkex', 'cz', 'dfkexbdkwwu', 'idkii', 'kz']

print("Looking for recurring patterns in outputs:")
for i, out in enumerate(outputs):
    print(f"Output {i} ('{out}'):")

    # Find repeated substrings
    substrings = {}
    for length in range(1, min(5, len(out)+1)):  # Check substrings up to length 4
        for start in range(len(out) - length + 1):
            substr = out[start:start+length]
            if substr in substrings:
                substrings[substr].append((start, i))
            else:
                substrings[substr] = [(start, i)]

    # Show substrings that appear more than once
    repeated = {k: v for k, v in substrings.items() if len(v) > 1}
    if repeated:
        print("  Repeated substrings:")
        for substr, positions in repeated.items():
            print(f"    '{substr}' appears at positions {positions}")
    else:
        print("  No repeated substrings found")

    print()

